def P(id, name, nameLocal, category, tier, emoji, coords, why, howToGet, transport, whatToDo, whenToCome,
      costLkr=None, costUsd=None, costNote=None, bring=(), pitfalls=(), contacts=(), bookAhead=None,
      tpl=None, travel=None, sources='', rating=None, hours=None, verified=False, gq=None, tags=()):
    d = dict(id=id, name=name, nameLocal=nameLocal, category=category, tier=tier, emoji=emoji,
             coords=coords, coordsVerified=verified, gmapsQuery=gq or (nameLocal + ', Sri Lanka'),
             why=list(why), howToGet=howToGet, transport=transport, whatToDo=list(whatToDo),
             whenToCome=whenToCome, bring=list(bring), pitfalls=list(pitfalls),
             contacts=[dict(kind=k, value=v, **({'label': l} if l else {})) for k, v, l in contacts],
             photos=[], sources=sources)
    for k, v in [('costLkr', costLkr), ('costUsd', costUsd), ('costNote', costNote), ('bookAhead', bookAhead),
                 ('messageTemplateId', tpl), ('travelTimeMin', travel), ('rating', rating), ('hours', hours)]:
        if v is not None: d[k] = v
    if tags: d['tags'] = list(tags)
    return d

