# ---------- Кафе Мириссы ----------
def CAFE(id, name, q, tier, emoji, coords, why, cuisine, check, stomach, hours=None, contacts=(), pitfalls=(), avoid=False, src='Чаты Мириссы 2025–2026', walk=None):
    d = P(id, name, q, 'food', tier, emoji, coords, why, f'От отеля пешком ~{walk} мин.' if walk else 'Тук-тук или пешком — посмотреть в Google Maps.',
          'walk' if walk and walk <= 15 else 'tuktuk', ['Поесть'], hours or 'Смотреть часы в Google Maps',
          costLkr=check, costNote='Средний чек на двоих, ориентир — уточнить по меню', pitfalls=pitfalls, contacts=contacts,
          sources=src, hours=hours, travel=walk, gq=q + ', Mirissa, Sri Lanka')
    d.update(cuisine=cuisine, stomach=stomach, menu=[], avoid=avoid)
    return d

