# ---------- Вся Шри-Ланка ----------
def ISL(id, name, q, cat, tier, emoji, coords, region, km, hours, trip, why, note=''):
    d = P(id, name, q, cat, tier, emoji, coords, why,
          f'От Мириссы ~{km} км, ~{hours} ч на машине в одну сторону. {note}'.strip(),
          'car_day' if trip in ('day',) else 'car_day', ['TODO: заполнить по исследованию'], 'TODO',
          sources='TODO: найти свежие отзывы 2025–2026')
    d.update(region=region, distanceKm=km, driveHours=hours, tripType=trip, inPlan=False)
    return d

